using BotFramework.Discord.Commands;using BotFramework.Discord.Routing;using Games.DiceCube.Application.Services;
namespace Games.DiceCube.Discord;
public sealed class DiceCubeDiscordHandler(IDiceCubeService service):IDiscordMessageHandler{public bool CanHandle(DiscordMessageContext context)=>DiscordCommand.Is(context,"dice");public async Task HandleAsync(DiscordMessageContext context){var p=DiscordCommand.Parts(context);if(p.Length!=2||!int.TryParse(p[1], System.Globalization.CultureInfo.InvariantCulture, out var amount)||amount<=0){await DiscordCommand.ReplyAsync(context,"Использование: `dice <ставка>`");return;}var u=DiscordCommand.UserId(context);var s=DiscordCommand.ScopeId(context);var src=DiscordCommand.SourceId(context);var n=DiscordCommand.DisplayName(context);_ = await service.PlaceBetAsync(u,n,s,amount,src,context.CancellationToken);var face=DiscordCommand.RandomFace(1,6);var r=await service.RollAsync(u,n,s,face,context.CancellationToken);await DiscordCommand.ReplyResultAsync(context,r,"Dice: "+face);}}
